// Build 1,000 sample latencies: 900 cache hits and 100 cache misses
const latencies = [];

for (let index = 0; index < 1000; index++) {
    // The first 900 are hits at 5 ms, the remaining 100 are misses at 200 ms
    if (index < 900) {
        latencies.push(5);
    } else {
        latencies.push(200);
    }
}

// Add up every latency, then divide by the count to get the mean
